    //println!("{},{},{},{}", fact_a, fact_b, fact_na, fact_nb);
    let mut ans = modPow(2, n as i64) - 1;
    let choose_na = fact_na * modInv(fact_a) % MOD;
    let choose_nb = fact_nb * modInv(fact_b) % MOD;
    ans = (ans + MOD + MOD - choose_na - choose_nb) % MOD;
