fn main() {
    input! {
        N: usize,
        Q: usize,
        tmpABs: [(usize, usize); N-1],
        tmpPXs: [(usize, i64); Q],
    }
    let ABs: Vec<(usize, usize)> = tmpABs.iter().map(|&(a, b)| (a - 1, b - 1)).collect();
    let PXs: Vec<(usize, i64)> = tmpPXs.iter().map(|&(p, x)| (p - 1, x)).collect();

    let mut neibours_list: Vec<Vec<usize>> = vec![Vec::new(); N];
    for &(a, b) in ABs.iter() {
        neibours_list[a].push(b);
        neibours_list[b].push(a);
    }

    let mut children_list: Vec<Vec<usize>> = vec![Vec::new(); N];

    // 根であるノード0からの有向グラフとして扱う
    // 幅優先探索
    // もう見たノード
    let mut checked_set: HashSet<usize> = HashSet::new();
    checked_set.insert(0);
    let mut q: VecDeque<usize> = VecDeque::new();
    for &neibour in neibours_list[0].iter() {
        if !checked_set.contains(&neibour) {
            children_list[0].push(neibour);
            q.push_back(neibour);
        }
    }

    while !q.is_empty() {
        let node = q.pop_front().unwrap();
        checked_set.insert(node);

        for &neibour in neibours_list[node].iter() {
            if !checked_set.contains(&neibour) {
                children_list[node].push(neibour);
                q.push_back(neibour);
            }
        }
    }

    //最後に解決すればよろしい
    let mut Points = vec![0i64; N];
    for &(p, x) in PXs.iter() {
        Points[p] += x;
    }

    // 親ノードから順に解決、ポイントを子に伝搬させていく
    // qは空になっているはずなので再利用しちゃう
    q.push_back(0);

    while !q.is_empty() {
        let node = q.pop_front().unwrap();
        let p = Points[node];

        for &child in children_list[node].iter() {
            Points[child] += p;
