    for i in ((n - b) as i64..=n as i64).rev() {
        fact = fact * i % MOD;
        match i {
            i if i == n - a + 1 => {
                fact_na = fact;
            }
            i if i == n - b + 1 => {
                fact_nb = fact;
            }
