    //     .clone()
    //     .into_iter()
    //     .filter(|s| s[0] != 'B' && s[s.len() - 1] != 'A')
    //     .collect();

    let mut XAs_rest = XAs.len();
    let mut BXs_rest = BXs.len();
    let mut BAs_rest = BAs.len();

    // まず、XAとBXの小さいほうに合わせて消費
    let smaller = min(XAs_rest, BXs_rest);
    ans += smaller;
    XAs_rest -= smaller;
    BXs_rest -= smaller;

    let bigger_rest = max(XAs_rest, BXs_rest);
    if smaller > 0 && bigger_rest == 0 {
        // 最初でぴったり消費できた場合
        // BA同士でくっつける
        let BAs_comb = if BAs_rest >= 2 { BAs_rest - 1 } else { 0 };
        ans += BAs_comb;
        BAs_rest = if BAs_rest >= 1 { 1 } else { 0 };

        // BAのかたまりをXA-BXに挟み込んで消勝することができる
        if BAs_rest > 0 {
            ans += 1;
        }
    } else {
        // まだ余っている場合

        // BA同士でくっつける
        let BAs_comb = if BAs_rest >= 2 { BAs_rest - 1 } else { 0 };
        ans += BAs_comb;
        BAs_rest = if BAs_rest >= 1 { 1 } else { 0 };

        if bigger_rest > 0 && BAs_rest > 0 {
            ans += 1
        }
    }

    println!("{}", ans);
}

