        gs[e.1].push(e.0);
    }

    let mut dp = vec![std::u64::MAX; n];
    let mut bh = std::collections::BinaryHeap::new();
    dp[0] = 0;
    bh.push(std::cmp::Reverse((0, 0)));

    while let Some(tup) = bh.pop() {
        let std::cmp::Reverse((cost, node)) = tup;
        if dp[node] < cost {
            continue;
        }

        let cost = cost + 1;
        for &g in &gs[node] {
