    do = []
    while L > 2:
        if L % 2 == 0:
            do.append('*2')
            L >>= 1
        else:
            do.append('+1')
            L -= 1
    do.reverse()

    vertex = 2
    l = 2
    edge = [[1, 2, 0], [1, 2, 1]]
    for op in do:
        if op == '*2':
            edge = [[v1, v2, c * 2] for v1, v2, c in edge]
            edge.append([vertex, vertex + 1, 0])
            edge.append([vertex, vertex + 1, 1])
            vertex += 1
            l *= 2
        elif op == '+1':
            edge.append([1, vertex, l])
            l += 1

    ans = '{} {}\n'.format(vertex, len(edge))
    ans += '\n'.join([' '.join(map(str, row)) for row in edge])
    return ans

